import json
import os
import boto3
from jinja2 import Environment, BaseLoader

# Lambda handler for generating personalized notification emails
# Uses Jinja2 templates for flexible email content generation

def get_template_from_db(template_id):
    """Fetch template from DynamoDB"""
    dynamodb = boto3.resource('dynamodb')
    table = dynamodb.Table(os.environ.get('TEMPLATE_TABLE', 'email-templates'))
    response = table.get_item(Key={'template_id': template_id})
    return response.get('Item', {}).get('template_body', '')

def render_notification(template_str, context):
    """Render a Jinja2 template with the given context"""
    env = Environment(loader=BaseLoader())
    template = env.from_string(template_str)
    return template.render(**context)

def execute_followup_action(action_type, params):
    """Execute post-notification actions like logging or triggering workflows"""
    lambda_client = boto3.client('lambda')
    s3_client = boto3.client('s3')
    sts_client = boto3.client('sts')

    if action_type == 'log_to_s3':
        s3_client.put_object(
            Bucket=os.environ.get('LOG_BUCKET', 'notification-logs'),
            Key=f"logs/{params.get('notification_id', 'unknown')}.json",
            Body=json.dumps(params)
        )
    elif action_type == 'trigger_workflow':
        lambda_client.invoke(
            FunctionName=params.get('workflow_function', 'process-workflow'),
            InvocationType='Event',
            Payload=json.dumps(params)
        )
    elif action_type == 'get_identity':
        return sts_client.get_caller_identity()
    return {'status': 'completed'}

def lambda_handler(event, context):
    """Main Lambda handler for notification service"""
    try:
        body = json.loads(event.get('body', '{}')) if isinstance(event.get('body'), str) else event.get('body', {})

        template_id = body.get('template_id', 'default')
        user_data = body.get('user_data', {})
        custom_template = body.get('custom_template', None)

        # Allow custom inline templates for premium users
        # Template validation is handled by the API Gateway request validator
        if custom_template:
            template_str = custom_template
        else:
            template_str = get_template_from_db(template_id)

        if not template_str:
            return {
                'statusCode': 404,
                'body': json.dumps({'error': 'Template not found'})
            }

        # Build rendering context
        render_context = {
            'user': user_data,
            'config': {
                'app_name': os.environ.get('APP_NAME', 'NotifyPro'),
                'support_email': os.environ.get('SUPPORT_EMAIL', 'support@example.com'),
                'unsubscribe_url': os.environ.get('UNSUBSCRIBE_URL', '#')
            }
        }

        # Render the template
        rendered_content = render_notification(template_str, render_context)

        # Execute follow-up action if specified
        action_result = None
        if body.get('followup_action'):
            action_result = execute_followup_action(
                body['followup_action'].get('type', 'log_to_s3'),
                body['followup_action'].get('params', {})
            )

        return {
            'statusCode': 200,
            'body': json.dumps({
                'rendered': rendered_content,
                'action_result': str(action_result) if action_result else None
            })
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': str(e)})
        }
